(()=>{'use strict';
const plan=window.LEMN_ASSET_PLAN,images=new Map(),decoded=new Set(),links=new Map(),routes=new Map();
const normalize=path=>path.replace(/\/$/,'')||'/';
const mobile=()=>matchMedia('(max-width:809px)').matches;
const photoPath=base=>mobile()?plan.variants[base]||base:base;
function imageReady(src,priority='auto'){if(images.has(src))return images.get(src).promise;const img=new Image();img.decoding='async';img.loading='eager';img.fetchPriority=priority;let resolve;const promise=new Promise(r=>resolve=r);images.set(src,{img,promise});img.onload=async()=>{try{await img.decode()}catch{}if(img.naturalWidth)decoded.add(src);resolve(!!img.naturalWidth)};img.onerror=()=>{images.delete(src);resolve(false)};img.src=src;if(img.complete&&img.naturalWidth){img.decode().catch(()=>{}).then(()=>{decoded.add(src);resolve(true)})}return promise;}
function resource(href,rel,as){const key=rel+'|'+href;if(links.has(key))return links.get(key);const existing=[...document.querySelectorAll('link')].find(l=>l.rel===rel&&l.getAttribute('href')===href);if(existing&&(rel!=='stylesheet'||existing.sheet))return Promise.resolve();const link=existing||document.createElement('link');link.rel=rel;link.href=href;if(as)link.as=as;if(as==='font')link.crossOrigin='anonymous';const promise=new Promise(resolve=>{link.onload=()=>resolve();link.onerror=()=>resolve()});links.set(key,promise);if(!existing)document.head.append(link);return promise;}
function moduleFor(path){if(['/dashboard','/agents','/privacy','/product-terms'].includes(path))return null;return plan.modules[path]||(path.startsWith('/learn/')?plan.modules['/learn/:nClQrfiKc']:path.startsWith('/markets/')?plan.modules['/markets/:Fe8F_Kjz3']:null);}
function pictures(path){const list=[plan.brand,...(plan.pages[path]||[]).map(photoPath)];if(path==='/')list.push('/assets/hero-wordmark.svg');{list.push(...['prCes9oaidK35fDMfOOUxQsAHCM','0AwtEmgx6SM5WkothpysVeZORL4','W2j7P007WypU7srPcJKNTGRTgE','g0SeyN4a2Nzx32mfNvkL6agosak','eTpMDTXkfIdP529bLnlvED2bYGE'].map(x=>'/assets/slots/'+x+'.svg?lm=9'))}return [...new Set(list)];}
function prepare(path,priority='auto'){path=normalize(path);const key=path+'|'+mobile();if(routes.has(key))return routes.get(key);const code=path==='/dashboard'?resource('/dashboard.js?v=11','modulepreload'):moduleFor(path)?resource(moduleFor(path),'modulepreload'):Promise.resolve();if(path==='/dashboard')resource('/dashboard.css?v=10','preload','style');const promise=Promise.all([code,...pictures(path).map((src,i)=>imageReady(src,i===0?'high':priority))]);routes.set(key,promise);return promise;}
window.LM_ASSETS={prepare,photoPath,imageReady,isReady:path=>pictures(normalize(path)).every(src=>decoded.has(src)),stylesheet:url=>resource(url,'stylesheet'),isDecoded:src=>decoded.has(src)};
plan.fonts.forEach(font=>resource(font,'preload','font'));plan.content.forEach(url=>fetch(url,{credentials:'same-origin',cache:'force-cache',priority:'low'}).catch(()=>{}));
prepare(location.pathname).then(()=>document.documentElement.dataset.lmAssetReady='true');
function intent(e){const link=e.target.closest?.('a[href]');if(!link||link.download||link.target==='_blank')return;const url=new URL(link.href,location.href);if(url.origin===location.origin&&!url.pathname.startsWith('/assets/'))prepare(url.pathname)}
document.addEventListener('pointerover',intent,{passive:true});document.addEventListener('focusin',intent);document.addEventListener('pointerdown',intent,{passive:true});
const idle=callback=>'requestIdleCallback' in window?requestIdleCallback(callback,{timeout:1200}):setTimeout(callback,150);
addEventListener('load',()=>idle(()=>{prepare('/dashboard');(async()=>{for(const route of ['/','/learn','/products','/markets','/protocol','/costs'])await prepare(route,'low')})();if(location.pathname.startsWith('/dashboard')){resource(plan.entry,'modulepreload');const home=moduleFor('/');if(home)resource(home,'modulepreload')}const cacheable=[...new Set(Object.values(plan.pages).flat().map(photoPath))];let index=0;async function worker(){while(index<cacheable.length){const url=cacheable[index++];if(decoded.has(url))continue;try{const response=await fetch(url,{credentials:'same-origin',cache:'force-cache',priority:'low'});if(response.ok)await response.arrayBuffer()}catch{}}}worker();worker();}));
})();
